// endsAndMeans — Iter 2.5 parser lexicon for the Ends-vs-Means split.
//
// Canonical source (DO NOT EDIT this file without re-reading these slides):
//   Tom Gilb, "Ends and Means" — Berlin 21 May 2026 MASTER deck (46 pages).
//   Local: 5 - Project/SEM App/assets/Ends and Means Berlin 21May2026 MASTER.pdf
//
// Specific slides this file implements:
//   • Slide 4 — End definition: "Future requirement, Objective, Goal, Aim,
//     Target, Value." (concept *100)
//   • Slide 6 — Means definition + synonyms: "Design Idea, Solution, Strategy,
//     Process Improvement Suggestion, Architecture, Ways, The How."
//   • Slide 8 — Keeney 3-level hierarchy: Fundamental Objectives → Strategic
//     Objectives → Means Objectives. One level's End = next level's Means.
//   • Slide 11 — Schopenhauer: "the confusion of ends and means"
//   • Slide 13 — Einstein: "the perfection of means and the confusion of ends
//     characterize our age."
//   • Slide 16 — Juran 1992 stated-needs vs real-needs: Food → Nourishment;
//     Auto → Transportation; House paint → Colorful-appearance + Freedom-
//     from-maintenance. This is the EXACT class of bug the old parser had
//     (stated need = means, real need = end). Iter 2.5 fixes it.
//   • Slide 20 — Ends spec table format: Value Tag / Value Full Name /
//     Ambition Level / Scale of Measure / Meter / Today's Status / Tolerable
//     Level / Wish Level. (Used by Iter 3, not yet here.)
//
// Tom's corrective examples (2026-05-14 chat):
//   "Windows S, need Cleanliness V, = improvement by washing m=means.
//    Garden=S, needs nourishment: Ends, by watering = means."
// → washing/watering are Means; Cleanliness/Nourishment are the Ends.
// → "by" is the Keeney-hierarchy connective between End and Means.
//
// The old parser tagged "washing", "watering", "renewal", "deletion",
// "new tyres", "upgrade" as Values. That is the category error this file
// repairs.

/**
 * Tier A — action nominals (gerunds and -ion / -ment / -ance nouns).
 * Each entry is a single lower-case lemma. Plural and -ing forms are
 * generated programmatically by `isMeansToken`.
 *
 * Source: Berlin slide 6 Means synonyms list, expanded with the everyday
 * action-nominals Tom used in his cabin/garden/car/contract examples.
 */
export const MEANS_TIER_A: ReadonlySet<string> = new Set([
  // Tom's anchor examples (2026-05-14)
  'washing', 'watering', 'renewal', 'deletion',
  // Cleaning + grounds
  'cleaning', 'sweeping', 'mowing', 'pruning', 'fertilizing', 'fertilising',
  'polishing', 'oiling', 'lubrication', 'dusting', 'vacuuming',
  // Building + envelope
  'painting', 'sealing', 'insulation', 'installation', 'weatherproofing',
  'caulking', 'roofing', 'rendering', 'plastering',
  // Lifecycle on objects
  'replacement', 'maintenance', 'repair', 'repairs', 'servicing', 'service',
  'inspection', 'refurbishment', 'renovation', 'restoration', 'overhaul',
  'rebuild', 'rebuilding',
  // Capability / functionality
  'upgrade', 'upgrading', 'downgrade', 'reconfiguration', 'calibration',
  'tuning', 'optimisation', 'optimization',
  // IT / digital
  'defragmenting', 'patching', 'updating', 'backup', 'backups', 'migration',
  'sync', 'syncing',
  // Compliance + governance
  'audit', 'auditing', 'review', 'verification', 'certification',
  'documentation', 'reporting', 'signoff', 'sign-off', 'approval',
  // Skills + culture
  'training', 'coaching', 'mentoring', 'onboarding', 'reskilling', 'upskilling',
  // Process improvement (Berlin slide 6 includes "Process Improvement Suggestion")
  'automation', 'streamlining', 'standardisation', 'standardization',
  'consolidation', 'rationalisation', 'rationalization',
])

/**
 * Tier C — Keeney-hierarchy connectives (Berlin slide 8). When these
 * appear between Y and Z in "X needs Y [connective] Z", Y is the End and
 * Z is the Means — regardless of whether Y/Z are individually classified
 * as quality or action nouns. The preposition itself disambiguates.
 *
 * "garden needs nourishment by watering"
 *   S = garden, V = nourishment, M = watering — no inference needed.
 */
export const KEENEY_CONNECTIVES = ['by', 'through', 'via', 'using', 'with'] as const

/**
 * Regex to match the connective between Y and Z, capturing both clauses.
 * Note `with` is in KEENEY_CONNECTIVES for awareness but DELIBERATELY
 * omitted from this regex because `splitValueWithRole` in SEMEntryForm
 * already claims "with" for stakeholder roles ("collaborate with the team").
 * Adding it here would clash with that rule.
 */
export const KEENEY_RE = /^(.+?)\s+(?:by|through|via|using)\s+(.+)$/i

/**
 * Quality nouns — when Y is one of these in "X needs Y", Y is definitively
 * an End (Value), regardless of any other rule. Short-circuits Tier A
 * checks so we never mis-tag "cleanliness" or "nourishment" as Means.
 */
export const QUALITY_NOUNS: ReadonlySet<string> = new Set([
  'cleanliness', 'nourishment', 'hydration', 'safety', 'security', 'privacy',
  'compliance', 'reliability', 'availability', 'functionality', 'usability',
  'performance', 'weatherproofing', 'comfort', 'appearance', 'tidiness',
  'freshness', 'health', 'validity', 'accuracy', 'integrity', 'durability',
  'longevity', 'sustainability', 'efficiency', 'capability', 'skill',
  'productivity', 'quality', 'speed', 'accuracy', 'transparency',
  'fairness', 'inclusion', 'accessibility', 'responsiveness',
  'profitability', 'growth', 'retention', 'satisfaction', 'wellbeing',
])

/**
 * Means → suggested End map. Seeded by Juran 1992 (Berlin slide 16) and
 * Tom's cabin/garden/car corrective examples (2026-05-14).
 *
 * **Honesty rule.** Any End inferred from this map is marked with the
 * `(?)` suffix in the parsed output so the user SEES it was inferred,
 * not silently invented. Berlin slide 11 (Schopenhauer) warns the
 * confusion of ends and means is the central danger.
 *
 * Keys are the lower-case lemma. Use `inferEndForMeans()` rather than
 * reading this directly so plurals and -ing variants resolve correctly.
 */
