/**
 * Solution-noun patterns (Tier B). Match phrases like "new tyres", "fresh
 * paint", "more storage", "additional units", "replacement parts". These
 * are Means by structure — the noun is the *thing acquired*, not a
 * quality desired of it. The End for "new tyres" is NOT inferable from
 * the structure alone (could be safety / image / grip), so callers leave
 * the End as `null` when only Tier B matches.
 *
 * Deliberately EXCLUDED (2026-05-14 Iter 2.5 refinement): "better X",
 * "improved X", "upgraded X". Those describe a desired quality OF X
 * ("the team wants better yield tracking" = End, not Means) — Berlin
 * slide 4: End is the future requirement / target / value. Letting those
 * adjectives count as Means would mis-classify the most common Value
 * phrasings.
 */
export const SOLUTION_NOUN_PREFIX_RE =
  /^(new|fresh|more|additional|replacement|spare|extra)\s+\w+/i

/** Suffix marker appended to inferred End strings so the chip renderer
 * can detect them and apply amber styling. The user can clear the marker
 * by editing the chip. */
export const INFERRED_SUFFIX = ' (?)'

/** True if the token (lower-cased) is a Means by Tier A or generated form. */
export function isMeansToken(tokenLc: string): boolean {
  if (MEANS_TIER_A.has(tokenLc)) return true
  // Generated -s plural and -ing variants
  if (tokenLc.endsWith('s')  && MEANS_TIER_A.has(tokenLc.slice(0, -1))) return true
  if (tokenLc.endsWith('es') && MEANS_TIER_A.has(tokenLc.slice(0, -2))) return true
  return false
}

/** True if the token (lower-cased) is a Quality noun (End by lexicon). */
export function isQualityToken(tokenLc: string): boolean {
  return QUALITY_NOUNS.has(tokenLc)
}

/**
 * Look up the suggested End for a Means token. Returns the canonical
 * End noun (e.g. "Cleanliness") or `null` if the Means is in the lexicon
 * but has no specific End mapping (callers should leave V as "?").
 */
export function inferEndForMeans(tokenLc: string): string | null {
  const direct = MEANS_TO_END.get(tokenLc)
  if (direct) return direct
  if (tokenLc.endsWith('s')  && MEANS_TO_END.has(tokenLc.slice(0, -1))) {
    return MEANS_TO_END.get(tokenLc.slice(0, -1)) ?? null
  }
  if (tokenLc.endsWith('es') && MEANS_TO_END.has(tokenLc.slice(0, -2))) {
    return MEANS_TO_END.get(tokenLc.slice(0, -2)) ?? null
  }
  return null
}

/** Result shape for `analyzeYClause`. */
export interface YClauseAnalysis {
  /** 'value' = treat Y as an End (existing parser path).
   *  'means' = treat Y as a Means, optionally with inferredEnd. */
  kind: 'value' | 'means'
  /** When kind === 'means', the original Y text (for the means chip). */
  means?: string
  /** When kind === 'means', the suggested End from MEANS_TO_END.
   *  `null` means "Means recognised but no End inferable" → V stays "?". */
  inferredEnd?: string | null
  /** When the input contained a Keeney connective ("by"/"through"/"via"),
   *  Y is split into explicit value + means. No inference needed. */
  explicitValue?: string
  /** When the input contained a Keeney connective, the means side. */
  explicitMeans?: string
}

/**
 * Analyze the Y clause of "[X] needs [Y]" — decide if Y is an End or a
 * Means, and if Means, infer the End where possible.
 *
 * Rules in priority order:
 *   1. Keeney connective ("Y by Z" / "Y through Z" / "Y via Z")
 *      → explicitValue=Y, explicitMeans=Z. No inference.
 *   2. First token is a Quality noun (Tier Q)
 *      → kind='value'. Existing parser path.
 *   3. First token is a Means token (Tier A, with plural/-ing folding)
 *      → kind='means', inferredEnd = MEANS_TO_END[token] OR null.
 *   4. Whole phrase matches Solution-noun prefix ("new X", "fresh X", …)
 *      → kind='means', inferredEnd=null. (Tom's "car needs new tyres".)
 *   5. Default
 *      → kind='value'. Existing parser path (recurses normally).
 */
export function analyzeYClause(y: string): YClauseAnalysis {
  const trimmed = y.trim()
  if (!trimmed) return { kind: 'value' }

  // Rule 1 — Keeney connective ("Y by Z")
  const keeney = trimmed.match(KEENEY_RE)
  if (keeney) {
    return {
      kind: 'means',
      explicitValue: keeney[1].trim(),
      explicitMeans: keeney[2].trim(),
    }
  }

  // Tokenise to get the head noun (skip determiners + adjectives no — keep simple:
  // first content word after stripping leading articles).
  const tokens = trimmed.split(/\s+/).filter(Boolean)
  let head = tokens[0]?.toLowerCase() ?? ''
  // Strip a single leading article so "the watering" / "an upgrade" still match.
  if (/^(the|a|an|some|any|its|their|our|my|your)$/i.test(head) && tokens.length > 1) {
    head = tokens[1].toLowerCase()
  }
  // Strip a single leading determiner-like adjective ("regular maintenance", "annual review")
  if (
    /^(regular|annual|monthly|weekly|daily|periodic|routine|scheduled|emergency|deep|light|heavy|full|partial|quick|thorough)$/i.test(head) &&
    tokens.length > 2
  ) {
    head = tokens[2].toLowerCase()
  }

  // Rule 2 — Quality noun → End
  if (isQualityToken(head)) return { kind: 'value' }

  // Rule 3 — Means token
  if (isMeansToken(head)) {
    return {
      kind: 'means',
      means: trimmed,
      inferredEnd: inferEndForMeans(head),
    }
  }

  // Rule 4 — Solution-noun prefix
  if (SOLUTION_NOUN_PREFIX_RE.test(trimmed)) {
    return {
      kind: 'means',
      means: trimmed,
      inferredEnd: null,
    }
  }

  // Rule 5 — default
  return { kind: 'value' }
}

/** True if the value chip text carries the inferred marker. */
export function isInferredEnd(chipText: string): boolean {
  return chipText.endsWith(INFERRED_SUFFIX)
}

/** Strip the inferred marker for display (chip rendering). */
export function stripInferredMarker(chipText: string): string {
  return isInferredEnd(chipText) ? chipText.slice(0, -INFERRED_SUFFIX.length) : chipText
}

/** Attach the inferred marker to an End string. */
export function withInferredMarker(end: string): string {
  return `${end}${INFERRED_SUFFIX}`
}
